import csv
import json
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple


def read_csv(path: Path) -> List[Dict[str, str]]:
    with path.open("r", encoding="utf-8", newline="") as f:
        reader = csv.DictReader(f)
        return [dict(row) for row in reader]


def load_manifest(path: Path) -> List[Dict[str, Any]]:
    data = json.loads(path.read_text(encoding="utf-8"))
    campaigns: List[Dict[str, Any]] = []
    for region in data.get("regions", []):
        for c in region.get("campaigns", []):
            campaigns.append(c)
    return campaigns


def is_blank(value: Any) -> bool:
    if value is None:
        return True
    if isinstance(value, str):
        return value.strip() == ""
    return False


def round2(x: float) -> float:
    return round(float(x), 2)


def latest_cycle_row(rows: List[Dict[str, str]]) -> Dict[str, str]:
    # cycle_tag is compared lexicographically per instructions
    return max(rows, key=lambda r: (r.get("cycle_tag") or ""))


def resolve_billing_row(
    billing_rows: List[Dict[str, str]],
    campaign_name: str,
    alias_labels: List[str],
) -> Dict[str, str]:
    labels = {campaign_name, *alias_labels}
    matched = [
        r
        for r in billing_rows
        if (r.get("campaign_label") in labels) and (r.get("status") == "active")
    ]
    if not matched:
        raise ValueError(
            f"No active billing row found for campaign_name={campaign_name!r} aliases={alias_labels!r}"
        )
    return latest_cycle_row(matched)


def build_active_clinics_map(
    override_rows: List[Dict[str, str]],
) -> Dict[str, Tuple[float, int]]:
    """Return map campaign_id -> (revision_number, active_clinics)."""
    best: Dict[str, Tuple[float, int]] = {}
    for r in override_rows:
        if r.get("state") != "approved":
            continue
        rev_raw = r.get("revision")
        clinics_raw = r.get("active_clinics")
        if is_blank(rev_raw) or is_blank(clinics_raw):
            continue
        try:
            rev = float(str(rev_raw).strip())
        except ValueError:
            continue
        try:
            clinics = int(float(str(clinics_raw).strip()))
        except ValueError:
            continue

        cid = r.get("campaign_id")
        if not cid:
            continue

        prev = best.get(cid)
        if prev is None or rev > prev[0]:
            best[cid] = (rev, clinics)

    return best


def build_crate_cost_map(crate_rows: List[Dict[str, str]]) -> Dict[str, float]:
    out: Dict[str, float] = {}
    for r in crate_rows:
        tier = (r.get("crate_tier") or "").strip()
        if not tier:
            continue
        cost_raw = r.get("crate_cost_usd")
        if is_blank(cost_raw):
            continue
        out[tier] = float(cost_raw)
    return out


def load_suspended_campaign_ids(susp_rows: List[Dict[str, str]]) -> set:
    return {
        (r.get("campaign_id") or "").strip()
        for r in susp_rows
        if (r.get("suspension_status") or "").strip() == "hold"
        and (r.get("campaign_id") or "").strip()
    }


def compute_model(
    payment_per_dispatch_per_clinic_usd: float,
    active_clinics: int,
    drug_cost_per_1000_doses_usd: float,
    doses_per_day: float,
    days_per_dispatch: int,
    dispatches_per_year: int,
    crate_cost_usd: float,
) -> Dict[str, Any]:
    annual_revenue = (
        payment_per_dispatch_per_clinic_usd * active_clinics * dispatches_per_year
    )
    annual_drug_cost = (
        drug_cost_per_1000_doses_usd
        * active_clinics
        * doses_per_day
        * days_per_dispatch
        * dispatches_per_year
        / 1000.0
    )

    # Per instructions (and absent tests clarifying otherwise), crate_cost_usd is per dispatch.
    annual_crate_cost = crate_cost_usd * dispatches_per_year

    annual_margin = annual_revenue - annual_drug_cost - annual_crate_cost

    return {
        "days_per_dispatch": int(days_per_dispatch),
        "dispatches_per_year": int(dispatches_per_year),
        "annual_revenue_usd": round2(annual_revenue),
        "annual_drug_cost_usd": round2(annual_drug_cost),
        "annual_crate_cost_usd": round2(annual_crate_cost),
        "annual_margin_usd": round2(annual_margin),
    }


def main() -> None:
    root = Path("/root")

    manifest_campaigns = load_manifest(root / "campaign_manifest.json")
    crate_rows = read_csv(root / "crate_cost.csv")
    billing_rows = read_csv(root / "billing.csv")
    override_rows = read_csv(root / "location_overrides.csv")
    susp_rows = read_csv(root / "suspensions.csv")

    suspended_hold = load_suspended_campaign_ids(susp_rows)

    # Step 2: filter campaigns
    retained = [
        c
        for c in manifest_campaigns
        if c.get("analysis_flag") == "review"
        and (c.get("campaign_id") not in suspended_hold)
    ]

    active_clinics_best = build_active_clinics_map(override_rows)
    crate_cost_by_tier = build_crate_cost_map(crate_rows)

    campaigns_out: List[Dict[str, Any]] = []

    total_margin_6 = 0.0
    total_margin_12 = 0.0

    for c in retained:
        campaign_id = c["campaign_id"]
        campaign_name = c["campaign_name"]
        alias_labels = c.get("alias_labels") or []
        crate_tier = c["crate_tier"]

        billing_row = resolve_billing_row(
            billing_rows=billing_rows,
            campaign_name=campaign_name,
            alias_labels=list(alias_labels),
        )
        payment = float(billing_row["payment_per_dispatch_per_clinic_usd"])
        billing_cycle_tag = billing_row.get("cycle_tag")
        billing_campaign_label = billing_row.get("campaign_label")

        if campaign_id in active_clinics_best:
            active_clinics = active_clinics_best[campaign_id][1]
            active_clinics_source = {
                "source": "location_overrides",
                "revision": active_clinics_best[campaign_id][0],
            }
        else:
            active_clinics = int(c["default_active_clinics"])
            active_clinics_source = {"source": "manifest_default"}

        if crate_tier not in crate_cost_by_tier:
            raise ValueError(
                f"No crate_cost_usd found for crate_tier={crate_tier!r} (campaign_id={campaign_id})"
            )
        crate_cost = float(crate_cost_by_tier[crate_tier])

        drug_cost_per_1000 = float(c["drug_cost_per_1000_doses_usd"])
        doses_per_day = float(c["doses_per_day"])

        model_6 = compute_model(
            payment_per_dispatch_per_clinic_usd=payment,
            active_clinics=active_clinics,
            drug_cost_per_1000_doses_usd=drug_cost_per_1000,
            doses_per_day=doses_per_day,
            days_per_dispatch=6,
            dispatches_per_year=60,
            crate_cost_usd=crate_cost,
        )
        model_12 = compute_model(
            payment_per_dispatch_per_clinic_usd=payment,
            active_clinics=active_clinics,
            drug_cost_per_1000_doses_usd=drug_cost_per_1000,
            doses_per_day=doses_per_day,
            days_per_dispatch=12,
            dispatches_per_year=30,
            crate_cost_usd=crate_cost,
        )

        margin_6 = float(model_6["annual_margin_usd"])
        margin_12 = float(model_12["annual_margin_usd"])
        diff = margin_12 - margin_6

        total_margin_6 += margin_6
        total_margin_12 += margin_12

        campaigns_out.append(
            {
                "campaign_id": campaign_id,
                "campaign_name": campaign_name,
                "crate_tier": crate_tier,
                "drug_cost_per_1000_doses_usd": round2(drug_cost_per_1000),
                "doses_per_day": doses_per_day,
                "active_clinics": int(active_clinics),
                "active_clinics_source": active_clinics_source,
                "billing": {
                    "campaign_label_matched": billing_campaign_label,
                    "cycle_tag": billing_cycle_tag,
                    "payment_per_dispatch_per_clinic_usd": round2(payment),
                },
                "crate_cost_usd": round2(crate_cost),
                "model_6_day": model_6,
                "model_12_day": model_12,
                "difference_usd": round2(diff),
            }
        )

    campaigns_out.sort(key=lambda x: x["campaign_id"])

    total_difference = total_margin_12 - total_margin_6
    abs_total_difference = abs(total_difference)

    decision_threshold = 11000.0
    decision = "move_to_12_day" if abs_total_difference < decision_threshold else "keep_6_day"

    analysis = {
        "assumptions": {
            "models": {
                "6_day": {"days_per_dispatch": 6, "dispatches_per_year": 60},
                "12_day": {"days_per_dispatch": 12, "dispatches_per_year": 30},
            },
            "crate_cost_basis": "per_dispatch",
            "decision_threshold_absolute_total_margin_difference_usd": decision_threshold,
            "currency_rounding": "round(value, 2)",
        },
        "campaigns": campaigns_out,
        "totals": {
            "campaign_count": len(campaigns_out),
            "total_margin_6_day_usd": round2(total_margin_6),
            "total_margin_12_day_usd": round2(total_margin_12),
            "total_difference_usd": round2(total_difference),
            "absolute_total_margin_difference_usd": round2(abs_total_difference),
        },
        "recommendation": {
            "decision": decision,
            "justification": (
                f"Absolute total margin difference is ${round2(abs_total_difference):,.2f} "
                f"vs threshold ${decision_threshold:,.2f}; therefore decision={decision}."
            ),
        },
    }

    (root / "vaxcrate_analysis.json").write_text(
        json.dumps(analysis, indent=2) + "\n", encoding="utf-8"
    )

    summary_lines = [
        f"Total 6-day margin (USD): {analysis['totals']['total_margin_6_day_usd']}",
        f"Total 12-day margin (USD): {analysis['totals']['total_margin_12_day_usd']}",
        f"Absolute difference (USD): {analysis['totals']['absolute_total_margin_difference_usd']}",
        f"Decision: {analysis['recommendation']['decision']}",
    ]

    (root / "vaxcrate_summary.md").write_text(
        "\n".join(summary_lines) + "\n", encoding="utf-8"
    )


if __name__ == "__main__":
    main()

